 "content": "def transform(grid):
    """Fill each top-open rectangular vessel and project from its opening."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            components.append(cells)

    for cells in components:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 3:
            continue
        top = [grid[r0][c] == 5 for c in range(c0, c1+1)]
        gaps = [i for i, present in enumerate(top) if not present]
        # A vessel has complete vertical sides and base, with one opening in its top.
        if len(gaps) != 1 or not all(top[0: gaps[0]]) or not all(top[gaps[0]+1:]):
            continue
        if any(grid[r][c0] != 5 or grid[r][c1] != 5 for r in range(r0, r1+1)):
            continue
        if any(grid[r1][c] != 5 for c in range(c0, c1+1)):
            continue
        gap = c0 + gaps[0]
        left_arm = gaps[0]
        right_arm = c1-c0-gaps[0]
        # Fill the opening and enclosed cavity.
        out[r0][gap] = 2
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        # Project horizontally above the vessel toward the longer top arm.
        if r0 > 0:
            if left_arm >= right_arm:
                for c in range(0, gap+1):
                    out[r0-1][c] = 2
            else:
                for c in range(gap, w):
                    out[r0-1][c] = 2
    return out
